definition.script:
pipeline {
    agent any

    stages {
        stage('Checkout') {
            steps {
                echo 'Step 1: Cloning source code from repository...'
                // Example: git url: 'https://github.com/your-username/your-repo.git', branch: 'main'
            }
        }

        stage('Hello') {
            steps {
                echo 'Step 2: Greeting team and validating environment...'
                echo 'Hello Ranjan! Pipeline initialization successful.'
            } 
        }

        stage('Build') {
            steps {
                echo 'Step 3: Compiling code and packaging artifacts...'
                echo 'Running build commands (e.g., mvn clean package)...'
            }
        }

        stage('Test') {
            steps {
                echo 'Step 4: Running automated unit tests...'
                echo 'Executing test suites (e.g., mvn test)...'
            }
        }

        stage('Deploy') {
            steps {
                echo 'Step 5: Deploying artifact to target server...'
                echo 'Copying war file to application server environment...'
            }
        }
    }

    // Post-build actions execute automatically based on the final status of the pipeline
    post {
        always {
            echo 'Cleaning up the build workspace...'
        }
        success {
            echo 'Pipeline completed successfully! Sending success alerts...'
        }
        failure {
            echo 'Pipeline failed! Sending failure notifications to the engineering team.'
        }
    }
}
